        "privacy.automatically_collected_information_is_kept": "<p>\uC790\uB3D9 \uC218\uC9D1\uB41C \uC815\uBCF4\uB294 \uC218\uC9D1\uC77C\uB85C\uBD80\uD130 \uCD5C\uB300 26\uAC1C\uC6D4\uAC04 \uBCF4\uAD00\uB418\uBA70, \uC774\uD6C4 \uC790\uB3D9\uC73C\uB85C \uD30C\uAE30\uB429\uB2C8\uB2E4.</p>",
        "privacy.device_information_device_type_operating": "\uC811\uC18D \uAE30\uAE30 \uC815\uBCF4 (\uAE30\uAE30 \uC720\uD615, \uC6B4\uC601\uCCB4\uC81C, \uBE0C\uB77C\uC6B0\uC800 \uC885\uB958)",
        "privacy.effective_date_december_4_2025": "\uC2DC\uD589\uC77C\uC790: 2025\uB144 12\uC6D4 4\uC77C",
        "privacy.gamerscroll_hereinafter": "\uAC8C\uC774\uBA38\uC2A4\uD06C\uB864(\uC774\uD558",
        "privacy.gamerscroll_privacy_policy_we_do": "\uAC8C\uC774\uBA38\uC2A4\uD06C\uB864\uC758 \uAC1C\uC778\uC815\uBCF4\uCC98\uB9AC\uBC29\uCE68. \uC9C1\uC811 \uC218\uC9D1\uD558\uB294 \uAC1C\uC778\uC815\uBCF4\uB294 \uC5C6\uC73C\uBA70, Google Analytics\uB97C \uD1B5\uD55C \uC775\uBA85 \uD1B5\uACC4\uB9CC \uC218\uC9D1\uD569\uB2C8\uB2E4.",
        "privacy.ip_address_anonymized": "IP \uC8FC\uC18C (\uC775\uBA85\uD654 \uCC98\uB9AC\uB428)",
        "privacy.privacy_policy_gamerscroll": "\uAC1C\uC778\uC815\uBCF4\uCC98\uB9AC\uBC29\uCE68, \uAC8C\uC774\uBA38\uC2A4\uD06C\uB864",
        "privacy.privacy_policy_gamerscroll_2": "\uAC1C\uC778\uC815\uBCF4\uCC98\uB9AC\uBC29\uCE68 | \uAC8C\uC774\uBA38\uC2A4\uD06C\uB864",
        "privacy.protects_users_personal_information_in": ")\uC740 \u300C\uAC1C\uC778\uC815\uBCF4 \uBCF4\uD638\uBC95\u300D \uBC0F \uAD00\uB828 \uBC95\uB839\uC5D0 \uB530\uB77C \uC774\uC6A9\uC790\uC758 \uAC1C\uC778\uC815\uBCF4\uB97C \uBCF4\uD638\uD558\uACE0, \uC774\uC640 \uAD00\uB828\uB41C \uACE0\uCDA9\uC744 \uC2E0\uC18D\uD558\uAC8C \uCC98\uB9AC\uD558\uAE30 \uC704\uD574 \uB2E4\uC74C\uACFC \uAC19\uC740 \uAC1C\uC778\uC815\uBCF4\uCC98\uB9AC\uBC29\uCE68\uC744 \uC218\uB9BD\xB7\uACF5\uAC1C\uD569\uB2C8\uB2E4.",
        "privacy.the_following_information_may_be": "\uC11C\uBE44\uC2A4 \uC774\uC6A9 \uACFC\uC815\uC5D0\uC11C \uC544\uB798\uC640 \uAC19\uC740 \uC815\uBCF4\uAC00 \uC790\uB3D9\uC73C\uB85C \uC0DD\uC131\uB418\uC5B4 \uC218\uC9D1\uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4:",
        "privacy.this_information_is_collected_through": "\uC774 \uC815\uBCF4\uB294 Google Analytics\uB97C \uD1B5\uD574 \uC218\uC9D1\uB418\uBA70, \uAC1C\uC778\uC744 \uC2DD\uBCC4\uD560 \uC218 \uC5C6\uB294 \uD1B5\uACC4 \uD615\uD0DC\uB85C\uB9CC \uD65C\uC6A9\uB429\uB2C8\uB2E4.",
        "privacy.this_privacy_policy_may_be": "<p>\uBCF8 \uAC1C\uC778\uC815\uBCF4\uCC98\uB9AC\uBC29\uCE68\uC740 \uBC95\uB839 \uB610\uB294 \uC11C\uBE44\uC2A4 \uBCC0\uACBD\uC5D0 \uB530\uB77C \uC218\uC815\uB420 \uC218 \uC788\uC73C\uBA70, \uBCC0\uACBD \uC2DC \uBCF8 \uD398\uC774\uC9C0\uB97C \uD1B5\uD574 \uACF5\uC9C0\uD569\uB2C8\uB2E4.</p>",
        "privacy.this_site": "\uBCF8 \uC0AC\uC774\uD2B8",
        "privacy.this_site_does_not_provide": "<p>\uBCF8 \uC0AC\uC774\uD2B8\uB294 \uC774\uC6A9\uC790\uC758 \uAC1C\uC778\uC815\uBCF4\uB97C \uC81C3\uC790\uC5D0\uAC8C \uC81C\uACF5\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uB2E4\uB9CC, Google Analytics \uC11C\uBE44\uC2A4 \uC774\uC6A9\uC744 \uC704\uD574 \uC775\uBA85\uD654\uB41C \uD1B5\uACC4 \uB370\uC774\uD130\uAC00 Google\uC5D0 \uC804\uC1A1\uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4.</p>",
        "privacy.this_site_uses_cookies_for": "<p>\uBCF8 \uC0AC\uC774\uD2B8\uB294 \uC774\uC6A9\uC790\uC758 \uD3B8\uC758\uB97C \uC704\uD574 \uCFE0\uD0A4\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4. \uCFE0\uD0A4\uB294 \uC6F9\uC0AC\uC774\uD2B8 \uC6B4\uC601\uC5D0 \uD544\uC694\uD55C \uAE30\uC220\uC801 \uC815\uBCF4\uB97C \uC800\uC7A5\uD558\uBA70, \uC774\uC6A9\uC790\uB294 \uBE0C\uB77C\uC6B0\uC800 \uC124\uC815\uC744 \uD1B5\uD574 \uCFE0\uD0A4 \uC800\uC7A5\uC744 \uAC70\uBD80\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.</p>",
